<script lang="ts">
 import {onMount,onDestroy,tick} from 'svelte';
 import {CompanyClient} from '$lib/utils/company-workspace';
 import {user} from '$lib/stores';
 import RoomConversationHost from './RoomConversationHost.svelte';
 export let companyId:string;export let owner:string;export let directory:any[]=[];
 let client:CompanyClient,rooms:any[]=[],notes:any[]=[],messages:any[]=[],active:any=null,error='',draft='',pending='',writeId='',thread:any=null;
 let open=false,full=false,min=false,busy=false,prefs={muted:false,quietStart:null as number|null,quietEnd:null as number|null,sound:false},toast:any=null;
 let cursor='',timer:ReturnType<typeof setInterval>,polling=false,alive=true,audio:AudioContext|null=null,noticeButton:HTMLButtonElement;
 let available=false,nextProbe=0,restoreRoom='';
 const seen=new Set<string>();const root=(id:string)=>'/rooms/'+encodeURIComponent(id);
 function speakerName(m:any){return m.speaker.id===$user?.id?$user.name:m.speaker.name||(/^[a-zA-Z0-9_.:-]{30,}$/.test(m.speaker.id)?m.speaker.kind==='agent'?'AI agent':'Team member':m.speaker.id);}
 function closeRoom(){active=null;messages=[];draft='';thread=null;try{sessionStorage.removeItem(dockKey());}catch{}}
 const dockKey=()=> 'sd.company-dock:'+encodeURIComponent(owner)+':'+encodeURIComponent(companyId);
 function quiet(p:any){if(p.muted)return true;if(p.quietStart===null||p.quietEnd===null)return false;const now=new Date(),m=now.getHours()*60+now.getMinutes();return p.quietStart<=p.quietEnd?m>=p.quietStart&&m<p.quietEnd:m>=p.quietStart||m<p.quietEnd;}
 async function poll(){if(polling||!alive||!available&&Date.now()<nextProbe)return;polling=true;try{
  if(!available){nextProbe=Date.now()+15000;const caps=await client.request('/capabilities');if(!alive)return;available=caps.humanMessaging===true;if(!available)return;}
  const [r,n]=await Promise.all([client.request('/rooms'),client.request('/notifications?after='+encodeURIComponent(cursor))]);if(!alive)return;
  const list=r.rooms||r.items||[];if(list.some((x:any)=>x.companyId!==companyId))throw Error('Company room scope could not be verified.');rooms=list;
  if(restoreRoom){const id=restoreRoom;restoreRoom='';if(rooms.some(r=>r.id===id))await showRoom({id});}
  for(const note of n.notifications){if(note.companyId!==companyId)throw Error('Notification scope could not be verified.');if(!seen.has(note.id)){seen.add(note.id);notes=[...notes,note].slice(-100);if(note.status==='SAVED'&&!note.preferences?.some(quiet)){toast=note;if(audio&&note.preferences?.some((p:any)=>p.sound)){const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);g.gain.value=.025;o.frequency.value=660;o.start();o.stop(audio.currentTime+.08);}}await client.request('/notifications/'+encodeURIComponent(note.id)+'/ack','POST',{kind:'delivered'});}}
  cursor=n.next;if(active){if(!rooms.some(x=>x.id===active.id)){active=null;messages=[];draft='';thread=null;}else await readMessages();}error='';
 }catch(e){if(alive){if([401,403,404].includes((e as any)?.status)){try{sessionStorage.removeItem(dockKey());}catch{}window.dispatchEvent(new CustomEvent('starli-company-access-lost',{detail:{companyId}}));}available=false;nextProbe=Date.now()+15000;rooms=[];messages=[];notes=[];toast=null;active=null;draft='';error=(e as Error).message;}}finally{polling=false;}}
 async function readMessages(){const id=active?.id,threadId=thread?.id??null;if(!id)return;const d=await client.request(root(id)+'/messages?limit=100'+(thread?'&threadRootId='+encodeURIComponent(thread.id):''));if(!alive||active?.id!==id||(thread?.id??null)!==threadId)return;const list=d.messages||d.items||[];if(list.some((x:any)=>x.roomId!==id))throw Error('Message room could not be verified.');messages=list;}
 async function showRoom(room:any){try{const d=await client.request(root(room.roomId||room.id));if(!alive)return;const r=d.room||d;if(r.companyId!==companyId)throw Error('Company room scope could not be verified.');active=r;try{sessionStorage.setItem(dockKey(),r.id);}catch{}draft='';pending='';thread=null;messages=[];min=false;await readMessages();toast=null;const p=await client.request('/notification-preferences?roomId='+encodeURIComponent(r.id));if(alive&&active?.id===r.id)prefs=p;await tick();}catch(e){error=(e as Error).message;}}
 async function send(){if(busy||!draft.trim()||!active)return;const room=active.id,threadId=thread?.id??null,sentDraft=draft,body=draft.trim(),fingerprint=JSON.stringify([room,threadId,body]);if(pending!==fingerprint){pending=fingerprint;writeId=crypto.randomUUID();}busy=true;
 try{const d=await client.request(root(room)+'/messages','POST',{content:body,parentId:threadId,mentions:[],dispatchAgentIds:[],attachmentIds:[]},writeId);if(!alive||active?.id!==room||(thread?.id??null)!==threadId)return;if(d.message?.roomId!==room||(d.message.parentId??null)!==threadId)throw Error('Message delivery could not be confirmed.');if(draft===sentDraft)draft='';pending='';await readMessages();error='';}catch(e){if(alive)error=(e as Error).message+' Delivery is unconfirmed; refresh before retrying.';}finally{if(alive)busy=false;}}
 async function savePrefs(){try{prefs=await client.request('/notification-preferences'+(active?'?roomId='+encodeURIComponent(active.id):''),'PUT',prefs);}catch(e){error=(e as Error).message;}}
 async function enableSound(){try{audio??=new AudioContext();await audio.resume();prefs={...prefs,sound:true};await savePrefs();}catch{error='Sound could not be enabled in this browser.';}}
 async function markRead(note:any){await showRoom(note);try{await client.request('/notifications/'+encodeURIComponent(note.id)+'/ack','POST',{kind:'read'});note.status='READ';notes=[...notes];}catch(e){error=(e as Error).message;}}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){alive=false;client.close();rooms=[];messages=[];notes=[];active=null;toast=null;draft='';}}
 onMount(()=>{client=new CompanyClient(companyId,()=>localStorage.token||'',fetch,true);try{restoreRoom=sessionStorage.getItem(dockKey())||'';}catch{}void poll();void client.request('/notification-preferences').then(p=>{if(alive&&!active)prefs=p;}).catch(()=>{});timer=setInterval(()=>{if(!document.hidden)void poll();},3000);window.addEventListener('storage',session);return()=>window.removeEventListener('storage',session);});onDestroy(()=>{alive=false;client?.close();clearInterval(timer);void audio?.close();});
</script>
<div class="company-messenger">
 {#if available}
 <button class="inbox sd-button" bind:this={noticeButton} aria-expanded={open} on:click={()=>open=!open}>Company inbox {notes.filter(n=>n.status!=='READ').length||''}</button>
 {#if toast}<div class="toast" role="status"><button on:click={()=>showRoom(toast)}>New company message · Open conversation</button><button aria-label="Dismiss notification" on:click={()=>toast=null}>×</button></div>{/if}
 {#if open}<section class="inbox-panel" aria-label="Company inbox"><h2>Company inbox</h2><p>Internal company messages</p>{#each notes as n}<button class="room" on:click={()=>showRoom(n)}>Message · {n.status.toLowerCase()} <span on:click|stopPropagation={()=>markRead(n)} role="button" tabindex="0" on:keydown={e=>{if(e.key==='Enter')void markRead(n);}}>Open and mark read</span></button>{/each}
 {#each rooms as room}<button class="room" on:click={()=>showRoom(room)}>{room.kind==='channel'?'# ':''}{room.name}<small>{room.unread||0} unread · {room.visibility==='public'?'Company members':'Restricted members'}</small></button>{/each}
 <details><summary>Notification preferences</summary><label><input type="checkbox" bind:checked={prefs.muted} on:change={savePrefs}/>Mute {active?'this conversation':'this company'}</label><button class="sd-button" on:click={enableSound}>Enable sound after this gesture</button><label>Quiet hours start (minutes after midnight)<input type="number" min="0" max="1439" bind:value={prefs.quietStart}/></label><label>Quiet hours end<input type="number" min="0" max="1439" bind:value={prefs.quietEnd}/></label><button on:click={savePrefs}>Save preferences</button></details>{#if error}<p role="alert">{error}</p>{/if}</section>{/if}
 {#if active}<section class="messenger" class:full class:mini={min} aria-label={active.name+' company conversation'}><header><button aria-expanded={!min} on:click={()=>min=!min}>{active.name}</button><button aria-label={full?'Restore compact chat':'Expand company chat'} on:click={()=>full=!full}>↗</button><button aria-label="Close company chat" on:click={closeRoom}>×</button></header><div class="company-conversation-content" hidden={min}><small>{active.visibility==='public'?'Company members':'Restricted conversation'}</small>{#if thread}<button on:click={()=>{thread=null;void readMessages();}}>← All messages</button>{/if}{#key active.id}<RoomConversationHost {owner} {companyId} room={active} {directory} {messages} bind:draft {busy} {error} sendMessage={send} refreshMessages={readMessages} on:thread={e=>{const message=messages.find(m=>m.id===e.detail);if(message){thread={...message,id:message.parentId||message.id};void readMessages();}}}/>{/key}{#if active.kind==='work_session'}<p>Read-only work transcript. Open Bot conversations for administrator controls.</p>{/if}{#if error}<p role="alert">{error}</p>{/if}</div></section>{/if}
 {/if}
</div>
<style>.company-conversation-content{display:flex;flex-direction:column;flex:1;min-height:0}.company-conversation-content[hidden]{display:none}.company-conversation-content>small{padding:8px;font-size:11px;color:var(--sd-muted);overflow-wrap:anywhere}.inbox{position:fixed;bottom:12px;left:14px;z-index:46}.inbox-panel,.toast,.messenger{position:fixed;border:1px solid var(--sd-line);background:var(--sd-card);color:var(--sd-text);border-radius:15px;box-shadow:0 10px 45px #25204d30;z-index:48}.inbox-panel{bottom:62px;left:12px;padding:16px;width:min(370px,calc(100vw - 24px));max-height:75dvh;overflow:auto}.inbox-panel h2{font-weight:700}.room{display:block;text-align:left;width:100%;border-bottom:1px solid var(--sd-line);padding:12px 0}.room small,.room span{display:block;font-size:12px;color:var(--sd-muted)}label{display:block;font-size:13px;margin:8px 0}input[type=number]{background:var(--sd-card);border:1px solid var(--sd-line);padding:8px;border-radius:8px;max-width:100%;width:100%}.toast{bottom:65px;right:12px;padding:12px;display:flex;gap:16px}.messenger{bottom:10px;right:12px;width:min(390px,calc(100vw - 24px));height:min(540px,80dvh);display:flex;flex-direction:column;overflow:hidden}.messenger header{display:flex;gap:8px;align-items:center;background:var(--sd-tint);padding:8px}.messenger header button{min-width:36px;min-height:36px}.messenger header button:first-child{flex:1;text-align:left;font-weight:700}.messenger.mini{height:54px}.messenger.full{inset:75px 18px 12px;width:auto;height:auto}@media(max-width:600px){.messenger:not(.mini){inset:6px 5px max(6px,env(safe-area-inset-bottom));width:auto;height:auto}.messenger header button{min-width:44px;min-height:44px}.toast{max-width:calc(100vw - 24px)}}</style>
